/* @socom-skeleton body StopRumbler__9CSealCtrlFv */
void CSealCtrl::StopRumbler()
{
    CPad* pad;
    
    if (m_padid < 2)
    {
        pad = CInput::m_pads[m_padid];
    }
    else
    {
        pad = NULL;
    }

    if (pad)
    {
        pad->m_ActData[1] = 0; /* 0x284294: both actuator bytes (+0xd, +0xc) */
        pad->m_ActData[0] = 0;
    }

    m_highrumbletime = 0.0f;
    m_rumbletime = 0.0f;
    m_rumblestr = 0.0f;

    CInput::Flush();
    CZSealBody::StopAllHeartbeatSounds();
}

